function PinModal({ deptLabel, onVerify, onClose }) {
  const [digits, setDigits] = useState(['','','','']);
  const [error, setError] = useState(false);
  const refs = [useRef(), useRef(), useRef(), useRef()];
  useEffect(() => { refs[0].current?.focus(); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const handleChange = (idx, val) => {
    const d = val.replace(/\D/g,'').slice(-1);
    const next = [...digits]; next[idx] = d; setDigits(next);
    if (d && idx < 3) refs[idx+1].current?.focus();
  };
  const handleKeyDown = (idx, e) => {
    if (e.key === 'Backspace' && !digits[idx] && idx > 0) { refs[idx-1].current?.focus(); }
  };
  const handleVerify = () => {
    const pin = digits.join('');
    if (pin.length < 4) return;
    if (onVerify(pin)) return;
    setError(true); setDigits(['','','','']);
    setTimeout(() => { setError(false); refs[0].current?.focus(); }, 1200);
  };
  const filled = digits.every(d => d !== '');
  return (
    <div style={{position:"fixed",inset:0,background:"#000000cc",zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:"#f3fffe",border:"2px solid #2BBFBA",borderRadius:16,padding:28,width:"100%",maxWidth:320,boxShadow:"0 30px 80px #000",textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>🔒</div>
        <div style={{fontSize:15,fontWeight:900,color:"#1a3635",marginBottom:4}}>{deptLabel} 編集ロック</div>
        <div style={{fontSize:12,color:"#5a9e9b",marginBottom:24}}>4桁のPINを入力してください</div>
        <div style={{display:"flex",gap:10,justifyContent:"center",marginBottom:16}}>
          {digits.map((d,i) => (
            <input key={i} ref={refs[i]} type="text" inputMode="numeric" maxLength={1} value={d}
              onChange={e=>handleChange(i,e.target.value)} onKeyDown={e=>handleKeyDown(i,e)}
              onKeyUp={e=>{ if(e.key==='Enter'&&filled) handleVerify(); }}
              style={{width:52,height:56,textAlign:"center",fontSize:24,fontWeight:900,border:`2px solid ${error?"#ef4444":d?"#2BBFBA":"#90cbc8"}`,borderRadius:10,background:error?"#fff0f0":"#fff",outline:"none",color:"#1a3635",caretColor:"transparent"}}/>
          ))}
        </div>
        {error && <div style={{color:"#ef4444",fontSize:12,marginBottom:12,fontWeight:700}}>PINが違います。もう一度お試しください。</div>}
        <button onClick={handleVerify} disabled={!filled} style={{width:"100%",background:filled?"linear-gradient(135deg,#2BBFBA,#45B7D1)":"#d5edeb",color:filled?"#fff":"#7a9e9b",border:"none",borderRadius:9,padding:"12px 0",cursor:filled?"pointer":"not-allowed",fontSize:14,fontWeight:800,marginBottom:10}}>🔓 解錠する</button>
        <button onClick={onClose} style={{width:"100%",background:"none",border:"none",color:"#9ca3af",cursor:"pointer",fontSize:13}}>キャンセル</button>
      </div>
    </div>
  );
}

const PASTE_SHIFT_MAP = {"早":"早番","早番":"早番","日":"日勤","日勤":"日勤","遅":"遅番","遅番":"遅番","夜":"夜勤","夜勤":"夜勤","明":"明け","明け":"明け","休":"休み","休み":"休み","公":"休み","公休":"休み","休日":"休み","振休":"休み","有":"有休","有休":"有休","有給":"有休","希":"希望休","希望休":"希望休","E":"早番","D":"日勤","L":"遅番","N":"夜勤"};
function parseExcelPasteData(tsvText, staffList, year, month, customShiftKeys=[]) {
  const normMap = {};
  Object.entries(PASTE_SHIFT_MAP).forEach(([k,v]) => { normMap[normName(k)] = v; });
  customShiftKeys.filter(Boolean).forEach(k => { normMap[normName(k)] = k; });
  const toShift = c => normMap[normName(String(c??'').trim())] || null;
  const isShift = c => !!toShift(c);
  const ROLE_WORDS = new Set(["常勤","非常勤","パート","嘱託","正規","委託","管理","職員","名前","氏名","スタッフ"]);
  const DOW_SET = new Set(["月","火","水","木","金","土","日"]);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const rows = tsvText.trim().split(/\r?\n/).map(r => r.split('\t'));
  console.log("[parseExcelPasteData] rows:", rows.length, "first3:", rows.slice(0,3).map(r=>r.slice(0,10)));
  if (rows.length < 2) return null;
  // Format B detection: row with 20+ sequential integers starting from 1
  let dateRowIdx = -1, dateColOffset = -1;
  for (let ri = 0; ri < Math.min(6, rows.length); ri++) {
    const row = rows[ri];
    let seqStart = -1, seqLen = 0;
    for (let ci = 0; ci < row.length; ci++) {
      const n = parseInt(String(row[ci]??'').trim(), 10);
      if (n === 1 && seqStart < 0) { seqStart = ci; seqLen = 1; }
      else if (seqStart >= 0 && n === seqLen + 1) seqLen++;
      else if (seqStart >= 0) break;
    }
    if (seqLen >= 20) { dateRowIdx = ri; dateColOffset = seqStart; break; }
  }
  console.log("[parseExcelPasteData] FormatB dateRowIdx:", dateRowIdx, "dateColOffset:", dateColOffset);
  const result = {}, matched = [], unmatched = [];
  if (dateRowIdx >= 0) {
    // Format B: col→day from date row (explicit date numbers)
    const colToDay = {};
    rows[dateRowIdx].forEach((c, ci) => { const n = parseInt(String(c??'').trim(), 10); if (n >= 1 && n <= 31) colToDay[ci] = n; });
    for (let ri = dateRowIdx + 1; ri < rows.length; ri++) {
      const row = rows[ri];
      const shiftCols = Object.keys(colToDay).filter(ci => isShift(row[ci])).map(Number);
      if (shiftCols.length < 3) continue;
      let nameCell = '';
      for (let ci = 0; ci < dateColOffset; ci++) {
        const v = String(row[ci]??'').trim();
        if (!v || v.length < 2 || /^\d/.test(v) || ROLE_WORDS.has(v) || isShift(v)) continue;
        nameCell = v; break;
      }
      if (!nameCell) continue;
      const staff = staffList.find(s => nameMatch(nameCell, s.name));
      if (!staff) { if (!unmatched.includes(nameCell)) unmatched.push(nameCell); continue; }
      if (!matched.includes(staff.name)) matched.push(staff.name);
      if (!result[staff.id]) result[staff.id] = {};
      shiftCols.forEach(ci => { const sk = toShift(row[ci]); if (sk) result[staff.id][colToDay[ci]] = sk; });
    }
  } else {
    // Format A: 月火水木金土日 header, column position = day number
    let headerRowIdx = -1, shiftStartCol = 1;
    for (let ri = 0; ri < Math.min(5, rows.length); ri++) {
      const row = rows[ri];
      const dowCount = row.filter(c => DOW_SET.has(String(c??'').trim())).length;
      console.log("[parseExcelPasteData] FormatA ri:", ri, "dowCount:", dowCount, "sample:", row.slice(0,8));
      if (dowCount >= 20) { headerRowIdx = ri; shiftStartCol = row.findIndex(c => DOW_SET.has(String(c??'').trim())); break; }
    }
    console.log("[parseExcelPasteData] FormatA headerRowIdx:", headerRowIdx, "shiftStartCol:", shiftStartCol);
    // Align shiftStartCol with day 1's actual DOW: verify 3 consecutive DOW chars match the month
    if (headerRowIdx >= 0) {
      const dowSeq = Array.from({length: 3}, (_, i) => ['日','月','火','水','木','金','土'][new Date(year, month, i+1).getDay()]);
      const hrow = rows[headerRowIdx];
      for (let ci = shiftStartCol; ci < Math.min(shiftStartCol + 5, hrow.length - 2); ci++) {
        if (dowSeq.every((d, k) => String(hrow[ci+k]??'').trim() === d)) { shiftStartCol = ci; break; }
      }
    }
    const colToDay = {};
    for (let i = 0; i < daysInMonth; i++) colToDay[shiftStartCol + i] = i + 1;
    for (let ri = (headerRowIdx >= 0 ? headerRowIdx + 1 : 0); ri < rows.length; ri++) {
      const row = rows[ri];
      const shiftCols = Object.keys(colToDay).filter(ci => isShift(row[Number(ci)])).map(Number);
      if (shiftCols.length < 3) continue;
      let nameCell = '';
      for (let ci = 0; ci < shiftStartCol; ci++) {
        const v = String(row[ci]??'').trim();
        if (!v || v.length < 2 || /^\d/.test(v) || ROLE_WORDS.has(v) || isShift(v)) continue;
        nameCell = v; break;
      }
      if (!nameCell) continue;
      const staff = staffList.find(s => nameMatch(nameCell, s.name));
      if (!staff) { if (!unmatched.includes(nameCell)) unmatched.push(nameCell); continue; }
      if (!matched.includes(staff.name)) matched.push(staff.name);
      if (!result[staff.id]) result[staff.id] = {};
      shiftCols.forEach(ci => { const sk = toShift(row[ci]); if (sk) result[staff.id][colToDay[ci]] = sk; });
    }
  }
  console.log("[parseExcelPasteData] result staffIds:", Object.keys(result).length, "matched:", matched, "unmatched:", unmatched);
  if (Object.keys(result).length === 0) return null;
  return { result, matched, unmatched };
}

function ExcelPasteModal({ onClose, onApply, staffList, year, month, customShiftKeys=[], deptShiftTypes=[], customShiftDefs=[] }) {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const days = Array.from({length: daysInMonth}, (_, i) => i + 1);
  const DOW = ['日','月','火','水','木','金','土'];
  const allCycleKeys = [...new Set([...(deptShiftTypes.length > 0 ? deptShiftTypes : ['早番','日勤','遅番','夜勤']), '休み', '有休', '希望休', ''])];

  const [gridData, setGridData] = useState({});
  const [unmatchedNames, setUnmatchedNames] = useState([]);
  const [parseError, setParseError] = useState('');
  const [pasting, setPasting] = useState(false);
  const [namedOrder, setNamedOrder] = useState(null); // staff IDs in paste order from step-1
  const [pasteStartDay, setPasteStartDay] = useState(1);
  const [lastPasteType, setLastPasteType] = useState(''); // 'full'|'names'|'shifts'

  const isShiftCell = (c) => {
    if (!c) return false;
    return PASTE_SHIFT_MAP[normName(String(c).trim())] != null ||
      customShiftKeys.some(k => normName(k) === normName(String(c).trim()));
  };
  const parseShiftCell = (c) => {
    if (!c) return null;
    const n = normName(String(c).trim());
    return PASTE_SHIFT_MAP[n] || (customShiftKeys.find(k => normName(k) === n)) || null;
  };

  const process = (text) => {
    setParseError('');
    const rows = text.trim().split(/\r?\n/).map(r => r.split('\t').map(c => String(c??'').trim()));
    const filled = rows.filter(r => r.some(c => c));
    if (filled.length === 0) { setParseError('データが空です。'); return; }

    const DOW_CHARS = new Set(['月','火','水','木','金','土','日']);
    const isNameLike = c => c && c.length >= 2 && !isShiftCell(c) && !/^\d+$/.test(c) && !DOW_CHARS.has(c);

    const totalShiftCells = filled.reduce((s, r) => s + r.filter(isShiftCell).length, 0);
    // Check if any cell (any column) has a recognizable staff name
    const anyColHasMatchedName = filled.some(r => r.some(cell => isNameLike(cell) && staffList.some(s => nameMatch(cell, s.name))));

    console.log('[paste detect] totalShiftCells:', totalShiftCells, 'anyColHasMatchedName:', anyColHasMatchedName, 'rows:', filled.length);

    // Case 1: Names-only paste (≤2 shift cells total → treat as names)
    if (totalShiftCells <= 2) {
      const order = [];
      const unmatched = [];
      filled.forEach(r => {
        const name = r.find(isNameLike);
        if (!name) return;
        const staff = staffList.find(s => nameMatch(name, s.name));
        if (staff && !order.includes(staff.id)) order.push(staff.id);
        else if (!staff && name.length >= 2) unmatched.push(name);
      });
      if (order.length > 0 || unmatched.length > 0) {
        if (order.length > 0) setNamedOrder(order);
        setUnmatchedNames(unmatched);
        setLastPasteType('names');
        if (order.length === 0) setParseError(`名前を認識しましたが、スタッフと一致しません: ${unmatched.join('、')}`);
        return;
      }
    }

    // Case 2: Shifts-only paste (has shifts but no matched staff name anywhere in data)
    if (totalShiftCells > 2 && !anyColHasMatchedName) {
      const order = namedOrder && namedOrder.length > 0 ? namedOrder : staffList.map(s => s.id);
      const shiftRows = filled.filter(r => r.some(c => c)); // all non-empty rows
      if (shiftRows.length > 0) {
        const newData = {};
        Object.entries(gridData).forEach(([id, d]) => { newData[id] = { ...d }; });
        shiftRows.forEach((row, ri) => {
          if (ri >= order.length) return;
          const staffId = order[ri];
          if (!newData[staffId]) newData[staffId] = {};
          row.forEach((cell, ci) => {
            const day = pasteStartDay + ci;
            if (day < 1 || day > daysInMonth) return;
            const sk = parseShiftCell(cell);
            if (sk) newData[staffId][day] = sk;
          });
        });
        setGridData(newData);
        setLastPasteType('shifts');
        if (!namedOrder) setParseError(''); // clear error, show info instead
        return;
      }
    }

    // Case 3: Full paste (names + shifts)
    const r = parseExcelPasteData(text, staffList, year, month, customShiftKeys);
    if (!r) { setParseError('シフトデータを読み取れませんでした。スタッフ名＋シフトの範囲を選択してCtrl+Cしてください。'); return; }
    setGridData(r.result);
    setUnmatchedNames(r.unmatched);
    setLastPasteType('full');
    if (r.matched.length > 0) {
      setNamedOrder(r.matched.map(name => staffList.find(s => s.name === name)?.id).filter(Boolean));
    }
  };

  const handlePasteEvent = (e) => { const text = e.clipboardData.getData('text'); if (text.trim()) { e.preventDefault(); process(text); } };

  const handleClickPaste = async () => {
    setPasting(true);
    try {
      const text = await navigator.clipboard.readText();
      if (!text.trim()) setParseError('クリップボードが空です。Excelで範囲を選択しCtrl+Cしてから押してください。');
      else process(text);
    } catch { setParseError('クリップボードを読み取れませんでした。Ctrl+Vで貼り付けてください。'); }
    setPasting(false);
  };

  const cycleCell = (staffId, day) => {
    setGridData(prev => {
      const cur = (prev[staffId] || {})[day] ?? '';
      const idx = allCycleKeys.indexOf(cur);
      const next = allCycleKeys[(idx + 1) % allCycleKeys.length];
      return { ...prev, [staffId]: { ...(prev[staffId] || {}), [day]: next } };
    });
  };

  const totalCells = Object.values(gridData).reduce((sum, d) => sum + Object.values(d).filter(v => v).length, 0);

  const handleApply = () => {
    const cleaned = {};
    Object.entries(gridData).forEach(([id, dayMap]) => {
      const filtered = Object.fromEntries(Object.entries(dayMap).filter(([, v]) => v));
      if (Object.keys(filtered).length > 0) cleaned[id] = filtered;
    });
    onApply(cleaned);
  };

  return (
    <div style={{position:'fixed',inset:0,background:'#000000cc',zIndex:200,display:'flex',alignItems:'center',justifyContent:'center',padding:8}}
      onPaste={handlePasteEvent}
      onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:'#f3fffe',border:'1px solid #90cbc8',borderRadius:14,padding:'16px 18px',width:'100%',maxWidth:960,maxHeight:'95vh',boxShadow:'0 30px 80px #000',display:'flex',flexDirection:'column',gap:10}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
          <div>
            <div style={{fontSize:15,fontWeight:900,color:'#1a3635'}}>📋 シフト貼り付けグリッド</div>
            <div style={{fontSize:11,color:'#3a8a87',marginTop:2}}>{year}年{month+1}月 ／ Ctrl+Vで読み込み・セルをクリックでシフト変更</div>
          </div>
          <button onClick={onClose} style={{background:'none',border:'none',color:'#3a8a87',cursor:'pointer',fontSize:20,lineHeight:1}}>✕</button>
        </div>

        {/* Step guide */}
        <div style={{background:'#e8f5f4',border:'1px solid #90cbc8',borderRadius:8,padding:'8px 12px',fontSize:11,color:'#1a5a57'}}>
          {lastPasteType === 'names'
            ? <span style={{color:'#16a34a',fontWeight:700}}>✅ ステップ1完了: {namedOrder?.length||0}名の名前を確認しました。次に先月末を除いた <b>シフト列だけ</b>（D〜AH等）をCtrl+Cして貼り付けてください。</span>
            : lastPasteType === 'shifts'
            ? <span style={{color:'#2563eb',fontWeight:700}}>✅ ステップ2完了: シフトをグリッドに反映しました。確認して「適用」してください。</span>
            : lastPasteType === 'full'
            ? <span style={{color:'#1a3635'}}>✅ 名前＋シフトを一括読み込みしました。</span>
            : <span><b>方法①</b> 名前列だけコピーして貼り付け → ②先月末を除くシフト列をコピーして貼り付け　　<b>方法②</b> 名前＋シフト（先月末含まず）をまとめてコピーして貼り付け</span>
          }
        </div>

        <div style={{display:'flex',gap:8,alignItems:'center',flexWrap:'wrap'}}>
          <button onClick={handleClickPaste} disabled={pasting}
            style={{background:'linear-gradient(135deg,#2BBFBA,#45B7D1)',color:'#fff',border:'none',borderRadius:9,padding:'8px 14px',cursor:'pointer',fontSize:13,fontWeight:800,whiteSpace:'nowrap'}}>
            {pasting ? '⏳ 読み込み中…' : '📋 クリップボードから読み込み'}
          </button>
          <span style={{fontSize:11,color:'#6ab5b2'}}>または画面にCtrl+V</span>
          {(lastPasteType === 'names' || lastPasteType === 'shifts') && (
            <div style={{display:'flex',alignItems:'center',gap:6,background:'#fff',border:'1px solid #90cbc8',borderRadius:8,padding:'4px 10px'}}>
              <span style={{fontSize:11,color:'#3a8a87',fontWeight:700}}>シフト開始日:</span>
              <button onClick={()=>setPasteStartDay(d=>Math.max(1,d-1))} style={{width:22,height:22,border:'1px solid #b8deda',borderRadius:4,background:'#d5edeb',cursor:'pointer',fontSize:12,fontWeight:700,padding:0}}>−</button>
              <span style={{fontSize:13,fontWeight:900,color:'#1a3635',minWidth:20,textAlign:'center'}}>{pasteStartDay}</span>
              <button onClick={()=>setPasteStartDay(d=>Math.min(daysInMonth,d+1))} style={{width:22,height:22,border:'1px solid #b8deda',borderRadius:4,background:'#d5edeb',cursor:'pointer',fontSize:12,fontWeight:700,padding:0}}>＋</button>
              <span style={{fontSize:11,color:'#3a8a87'}}>日から</span>
            </div>
          )}
          {unmatchedNames.length > 0 && (
            <div style={{background:'#fff8e1',border:'1px solid #f59e0b',borderRadius:8,padding:'3px 10px',fontSize:11,color:'#b45309',fontWeight:700}}>
              ⚠️ 未マッチ: {unmatchedNames.join('、')}
            </div>
          )}
        </div>

        {parseError && (
          <div style={{background:'#fff0f0',border:'1px solid #dc2626',borderRadius:8,padding:'7px 12px',color:'#dc2626',fontSize:12}}>{parseError}</div>
        )}

        <div style={{overflowX:'auto',overflowY:'auto',flex:1,border:'1px solid #b8deda',borderRadius:8,minHeight:0}}>
          <table style={{borderCollapse:'collapse',fontSize:11,tableLayout:'fixed',minWidth:'max-content',width:'100%'}}>
            <thead>
              <tr style={{position:'sticky',top:0,zIndex:2}}>
                <th style={{width:88,padding:'5px 8px',border:'1px solid #b8deda',textAlign:'left',fontWeight:700,color:'#1a3635',position:'sticky',left:0,zIndex:3,background:'#c8e8e5'}}>スタッフ</th>
                {days.map(d => {
                  const dow = new Date(year, month, d).getDay();
                  return (
                    <th key={d} style={{width:34,padding:'2px 1px',border:'1px solid #b8deda',textAlign:'center',fontWeight:700,background:'#d5edeb',
                      color: dow===0?'#e53935':dow===6?'#1E88E5':'#1a3635'}}>
                      <div style={{fontSize:11}}>{d}</div>
                      <div style={{fontSize:9,fontWeight:400}}>{DOW[dow]}</div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {(namedOrder
                ? [...namedOrder.map(id => staffList.find(s => s.id === id)).filter(Boolean),
                   ...staffList.filter(s => !namedOrder.includes(s.id))]
                : staffList
              ).map((s, si) => {
                const isNamed = namedOrder?.includes(s.id);
                const namedIdx = namedOrder?.indexOf(s.id) ?? -1;
                const staffShifts = gridData[s.id] || {};
                return (
                  <tr key={s.id} style={{background: si%2===0 ? '#fff' : '#f7fdfc'}}>
                    <td style={{padding:'3px 8px',border:'1px solid #b8deda',fontWeight:600,color:'#1a3635',
                      background: isNamed ? (si%2===0 ? '#d5f0e8' : '#c8eadf') : (si%2===0 ? '#e8f5f4' : '#ddf0ee'),
                      position:'sticky',left:0,zIndex:1,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis',maxWidth:88,fontSize:11}}>
                      {isNamed && <span style={{fontSize:9,color:'#16a34a',marginRight:3}}>#{namedIdx+1}</span>}
                      {s.name}
                    </td>
                    {days.map(d => {
                      const sk = staffShifts[d] || '';
                      const def = getShiftDef(sk, customShiftDefs);
                      return (
                        <td key={d} onClick={() => cycleCell(s.id, d)}
                          style={{width:34,padding:'2px 1px',border:'1px solid #ddd',textAlign:'center',cursor:'pointer',
                            background: sk ? def.bg : 'inherit',
                            color: sk ? def.color : '#ccc',
                            fontWeight: sk ? 700 : 400,
                            userSelect:'none',fontSize:11}}>
                          {sk ? (def.short || sk) : '－'}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div style={{display:'flex',gap:6,flexWrap:'wrap',alignItems:'center'}}>
          <span style={{color:'#3a8a87',fontWeight:700,fontSize:11}}>凡例:</span>
          {allCycleKeys.filter(k => k !== '').map(k => {
            const def = getShiftDef(k, customShiftDefs);
            return <span key={k} style={{background:def.bg,border:`1px solid ${def.border}`,borderRadius:6,padding:'2px 7px',color:def.color,fontWeight:700,fontSize:11}}>{k}</span>;
          })}
        </div>

        <div style={{display:'flex',gap:10}}>
          <button onClick={handleApply} disabled={totalCells === 0}
            style={{flex:2,background:totalCells>0?'linear-gradient(135deg,#2d8a52,#2a7a6e)':'#b0cece',color:'#fff',border:'none',borderRadius:8,padding:'11px 0',cursor:totalCells>0?'pointer':'default',fontSize:14,fontWeight:800}}>
            ✅ このシフトを適用する{totalCells>0?` (${totalCells}件)`:''}
          </button>
          <button onClick={onClose}
            style={{flex:1,background:'#d5edeb',color:'#3a8a87',border:'1px solid #90cbc8',borderRadius:8,padding:'11px 0',cursor:'pointer',fontSize:14}}>
            キャンセル
          </button>
        </div>
      </div>
    </div>
  );
}

function ExcelImportModal({ onImport, onReset, onClose, currentTrend, onConfirm, exceptionMonths = [], onExceptionMonthsChange, excelRawMonths = {}, onExcelRawMonthsChange, onAutoSetRatios, staffList = [], customShiftKeys = [] }) {
  const [status, setStatus] = useState("idle"), [preview, setPreview] = useState(null), [errorMsg, setErrorMsg] = useState("");
  const [unmatchedNames, setUnmatchedNames] = useState([]); // ① 名前不一致スタッフ一覧
  const [exInput, setExInput] = useState(""); // "YYYY-M" 入力用
  const fileRef = useRef(null);
  const handleFile = async (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    if (!window.XLSX) { setErrorMsg("ライブラリ読み込み中…"); setStatus("error"); return; }
    setStatus("parsing"); setErrorMsg(""); setUnmatchedNames([]);
    try {
      const buf=await file.arrayBuffer(); const wb=window.XLSX.read(buf,{type:"array"}); const trend=parseShiftExcel(wb, customShiftKeys);
      const trendStaffCount = Object.keys(trend).filter(k=>k!=='_months'&&k!=='_rawByMonth').length;
      if(trendStaffCount===0){setErrorMsg("シフトデータを読み取れませんでした。シート名に年月（例: 2026年5月・令和8年5月・5月）が含まれているか確認してください。");setStatus("error");if(fileRef.current)fileRef.current.value="";return;}
      // ① Excelの名前とアプリのスタッフ名を照合して不一致を検出
      const excelNames = new Set();
      Object.values(trend._rawByMonth||{}).forEach(monthData => Object.keys(monthData).forEach(n => excelNames.add(n)));
      const unmatched = [...excelNames].filter(n => !staffList.some(s => nameMatch(n, s.name)));
      setUnmatchedNames(unmatched);
      setPreview(trend); setStatus("done");
    }
    catch(err) { setErrorMsg("読み込み失敗: "+err.message); setStatus("error"); }
    finally { if(fileRef.current)fileRef.current.value=""; }
  };
  const addException = () => {
    const val = exInput.trim();
    if (!val) return;
    // "YYYY-M" または "YYYY/M" または "YYYY年M月" を正規化
    const m = val.match(/(\d{4})[年\-\/](\d{1,2})/);
    if (!m) { alert('形式は「2024-3」または「2024年3月」で入力してください'); return; }
    const key = `${m[1]}-${parseInt(m[2])}`;
    if (!exceptionMonths.includes(key)) onExceptionMonthsChange([...exceptionMonths, key].sort());
    setExInput("");
  };
  const removeException = (key) => onExceptionMonthsChange(exceptionMonths.filter(k => k !== key));
  return (
    <div style={{position:"fixed",inset:0,background:"#000000cc",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:"#f3fffe",border:"1px solid #90cbc8",borderRadius:14,padding:24,width:"100%",maxWidth:480,maxHeight:"85vh",overflowY:"auto",boxShadow:"0 30px 80px #000"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}><div><div style={{fontSize:15,fontWeight:900,color:"#1a3635"}}>📊 過去シフトから傾向を学習</div><div style={{fontSize:11,color:"#3a8a87",marginTop:3}}>過去のExcelシフト表を読み込んで自動生成に反映</div></div><button onClick={onClose} style={{background:"none",border:"none",color:"#3a8a87",cursor:"pointer",fontSize:20}}>✕</button></div>
        {currentTrend&&Object.keys(currentTrend).filter(k=>k!=='_months').length>0&&(()=>{
          const trendNames = Object.keys(currentTrend).filter(k=>k!=='_months');
          const matchedStaff = staffList.filter(s => trendNames.some(tn => nameMatch(tn, s.name)));
          return(
          <div style={{background:"#e8f5ee",border:"1px solid #14532d",borderRadius:8,padding:"8px 12px",marginBottom:14,fontSize:11}}>
            <div style={{color:"#5cb87a",fontWeight:700,marginBottom:6}}>✅ 現在 {trendNames.length} 名分の傾向データを保持中</div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
              {onAutoSetRatios&&matchedStaff.length>0&&<button onClick={()=>{
                const ratioMap={};
                for(const s of matchedStaff){
                  const tn=trendNames.find(k=>nameMatch(k, s.name));
                  if(!tn)continue;
                  const td=currentTrend[tn];
                  const r={};
                  ['早番','日勤','遅番','夜勤'].forEach(k=>{if(td[k]>0.01)r[k]=td[k];});
                  if(Object.keys(r).length>0)ratioMap[s.name]=r;
                }
                if(Object.keys(ratioMap).length>0){onAutoSetRatios(ratioMap);alert(`${Object.keys(ratioMap).length}名の勤務比率を自動セットしました。`);}
              }} style={{background:'#d1fae5',border:'1px solid #16a34a',borderRadius:5,color:'#15803d',fontSize:10,padding:'3px 10px',cursor:'pointer',fontWeight:700}}>📊 比率を自動セット（{matchedStaff.length}名）</button>}
              <button onClick={()=>onConfirm('傾向データをリセットします。よろしいですか？',()=>{try{localStorage.removeItem('shiftNavi_shiftTrend');}catch{}onReset();},'リセット')} style={{background:'#fff0f0',border:'1px solid #e07070',borderRadius:5,color:'#c44b4b',fontSize:10,padding:'3px 8px',cursor:'pointer'}}>🗑 リセット</button>
            </div>
          </div>);
        })()}
        <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" onChange={handleFile} style={{display:"none"}}/>
        <button onClick={()=>fileRef.current?.click()} style={{width:"100%",background:"linear-gradient(135deg,#2BBFBA,#45B7D1)",color:"#fff",border:"none",borderRadius:9,padding:"13px 0",cursor:"pointer",fontSize:14,fontWeight:800,marginBottom:14,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>📂 Excelファイルを選択</button>
        {status==="parsing"&&<div style={{textAlign:"center",color:"#2BBFBA",padding:"16px 0"}}>⏳ 解析中…</div>}
        {status==="error"&&<div style={{background:"#fff0f0",border:"1px solid #dc2626",borderRadius:8,padding:"10px 14px",color:"#f87171",fontSize:12,marginBottom:14}}>{errorMsg}</div>}
        {status==="done"&&preview&&(<div>
          <div style={{color:"#5cb87a",fontSize:13,fontWeight:700,marginBottom:6}}>✅ {Object.keys(preview).filter(k=>k!=='_months'&&k!=='_rawByMonth').length} 名分のデータを読み込みました</div>
          {unmatchedNames.length>0&&(
            <div style={{background:"#fff8e1",border:"2px solid #f59e0b",borderRadius:8,padding:"10px 14px",marginBottom:12}}>
              <div style={{color:"#b45309",fontWeight:800,fontSize:12,marginBottom:6}}>⚠️ アプリに存在しないスタッフ名（{unmatchedNames.length}件）— 学習対象外になります</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:6}}>
                {unmatchedNames.map(n=><span key={n} style={{background:"#fef3c7",border:"1px solid #f59e0b",borderRadius:12,padding:"2px 8px",fontSize:11,color:"#92400e"}}>{n}</span>)}
              </div>
              <div style={{fontSize:10,color:"#92400e"}}>スタッフ設定の名前を上記に合わせるか、Excelの名前を修正してください。</div>
            </div>
          )}
          <div style={{display:"flex",gap:10}}><button onClick={()=>onImport(preview)} style={{flex:1,background:"linear-gradient(135deg,#2d8a52,#2a7a6e)",color:"#fff",border:"none",borderRadius:8,padding:"11px 0",cursor:"pointer",fontSize:14,fontWeight:800}}>✅ 適用する</button><button onClick={onClose} style={{flex:1,background:"#d5edeb",color:"#3a8a87",border:"1px solid #90cbc8",borderRadius:8,padding:"11px 0",cursor:"pointer",fontSize:14}}>キャンセル</button></div>
        </div>)}
        {/* インポート済み月一覧 */}
        {Object.keys(excelRawMonths).length > 0 && (
          <div style={{marginTop:20,borderTop:"1px solid #b8deda",paddingTop:16}}>
            <div style={{fontSize:13,fontWeight:800,color:"#1a3635",marginBottom:4}}>📅 インポート済み月</div>
            <div style={{fontSize:11,color:"#3a8a87",marginBottom:8}}>不要な月を削除すると学習から除外されます（元に戻すには再インポートが必要）。</div>
            <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
              {Object.keys(excelRawMonths).sort().map(k => {
                const [y,m] = k.split('-').map(Number);
                const isExcl = exceptionMonths.includes(k);
                const staffCount = Object.keys(excelRawMonths[k]||{}).length;
                const now2 = new Date();
                const mAgo2 = now2.getFullYear()*12+now2.getMonth()-(y*12+(m-1));
                const remaining2 = 24-mAgo2;
                return (
                  <div key={k} style={{background:isExcl?"#fff0f0":"#e8f5ee",border:`1px solid ${isExcl?"#e07070":"#5cb87a"}`,borderRadius:16,padding:"3px 10px",fontSize:11,color:isExcl?"#c44b4b":"#2d8a52",display:"flex",alignItems:"center",gap:6}}>
                    <span>{y}年{m}月</span>
                    <span style={{fontSize:9,opacity:0.7}}>{staffCount}名{isExcl?" (除外中)":""} · {remaining2}ヶ月後に自動削除</span>
                    <button onClick={()=>onConfirm(`${y}年${m}月のデータを削除しますか？\n元に戻すには再インポートが必要です。`,()=>{
                      const newRaw = {...excelRawMonths}; delete newRaw[k];
                      if(onExcelRawMonthsChange) onExcelRawMonthsChange(newRaw);
                    },'削除')} style={{background:"none",border:"none",color:"#c44b4b",cursor:"pointer",fontSize:13,padding:0,lineHeight:1}}>🗑</button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
        {/* 例外月設定 */}
        <div style={{marginTop:20,borderTop:"1px solid #b8deda",paddingTop:16}}>
          <div style={{fontSize:13,fontWeight:800,color:"#1a3635",marginBottom:4}}>🚫 例外月（一時除外・自動期限切れ）</div>
          <div style={{fontSize:11,color:"#3a8a87",marginBottom:10}}>インフルエンザ・コロナ等でシフトが崩れた月を除外すると学習精度が上がります。</div>
          <div style={{display:"flex",gap:6,marginBottom:8}}>
            <input value={exInput} onChange={e=>setExInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addException()} placeholder="例: 2024-1 または 2024年1月" style={{flex:1,border:"1px solid #90cbc8",borderRadius:6,padding:"6px 10px",fontSize:12,color:"#1a3635",outline:"none"}}/>
            <button onClick={addException} style={{background:"#2BBFBA",color:"#fff",border:"none",borderRadius:6,padding:"6px 12px",cursor:"pointer",fontSize:12,fontWeight:700}}>追加</button>
          </div>
          {exceptionMonths.length===0
            ? <div style={{fontSize:11,color:"#8ecece"}}>除外月なし（すべての月を学習に使用）</div>
            : <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                {exceptionMonths.map(k=>{const [y,m]=k.split('-').map(Number);const now=new Date();const mAgo=now.getFullYear()*12+now.getMonth()-(y*12+(m-1));const remaining=18-mAgo;return(
                  <div key={k} style={{background:"#fff0f0",border:"1px solid #e07070",borderRadius:16,padding:"3px 10px",fontSize:11,color:"#c44b4b",display:"flex",alignItems:"center",gap:6}}>
                    <span>{y}年{m}月</span>
                    <span style={{fontSize:9,color:"#e07070",opacity:0.8}}>{remaining}ヶ月後に自動削除</span>
                    <button onClick={()=>removeException(k)} style={{background:"none",border:"none",color:"#c44b4b",cursor:"pointer",fontSize:13,padding:0,lineHeight:1}}>✕</button>
                  </div>
                );})}
              </div>
          }
        </div>
        {status==="idle"&&<button onClick={onClose} style={{width:"100%",background:"#d5edeb",color:"#3a8a87",border:"1px solid #90cbc8",borderRadius:8,padding:"11px 0",cursor:"pointer",fontSize:14,marginTop:16}}>閉じる</button>}
      </div>
    </div>
  );
}

function BulkKyukoModal({ staffList, year, month, onApply, onClose }) {
  const mk = monthKey(year, month);
  const initDays = () => { const first = staffList[0]; return first ? (first.kyukoDaysByMonth?.[mk] ?? first.kyukoDays ?? 8) : 8; };
  const [days, setDays] = useState(initDays);
  const setVal = (v) => setDays(Math.max(0, Math.min(20, +v || 0)));
  const [kp, setKp] = useState(null);
  const totalStaff = staffList.length;
  return (
    <div style={{position:"fixed",inset:0,background:"#000000cc",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:"#f3fffe",border:"1px solid #90cbc8",borderRadius:14,padding:24,width:"100%",maxWidth:360,boxShadow:"0 30px 80px #000"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}><div><div style={{fontSize:15,fontWeight:900,color:"#1a3635"}}>📅 休み日数 一括設定</div><div style={{fontSize:11,color:"#3a8a87",marginTop:2}}>{year}年{month+1}月</div></div><button onClick={onClose} style={{background:"none",border:"none",color:"#3a8a87",cursor:"pointer",fontSize:20}}>✕</button></div>
        <div style={{fontSize:11,color:"#2a5a57",marginBottom:20,marginTop:8,background:"#d5edeb",borderRadius:7,padding:"8px 12px",border:"1px solid #0e3a38"}}>💡 施設全体の休み日数を設定します。全部署・全スタッフ（{totalStaff}名）に一括適用されます。</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:12,marginBottom:28,background:"#d5edeb",borderRadius:12,padding:"18px 20px",border:"1px solid #90cbc8"}}>
          <button onClick={()=>setVal(days-1)} style={{background:"#b8deda",border:"1px solid #1a4040",borderRadius:8,color:"#1a4040",cursor:"pointer",width:40,height:40,fontSize:22,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center"}}>−</button>
          <div style={{textAlign:"center"}}>
            <div onClick={e=>setKp({value:days,min:0,max:20,unit:"日",onConfirm:v=>setVal(v===""?0:+v),anchorRect:e.currentTarget.getBoundingClientRect()})} style={{width:72,background:"#f0fffe",border:"2px solid #2BBFBA",borderRadius:8,color:"#2BBFBA",fontSize:28,fontWeight:900,textAlign:"center",padding:"6px 0",cursor:"pointer",userSelect:"none",display:"flex",alignItems:"center",justifyContent:"center",minHeight:48}}>{days}</div>
            <div style={{fontSize:12,color:"#2a5a57",marginTop:4,fontWeight:700}}>日 / 月</div>
          </div>
          <button onClick={()=>setVal(days+1)} style={{background:"#b8deda",border:"1px solid #1a4040",borderRadius:8,color:"#1a4040",cursor:"pointer",width:40,height:40,fontSize:22,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center"}}>＋</button>
        </div>
        <div style={{display:"flex",gap:10}}><button onClick={()=>onApply(days,mk)} style={{flex:1,background:"linear-gradient(135deg,#2BBFBA,#45B7D1)",color:"#fff",border:"none",borderRadius:8,padding:"11px 0",cursor:"pointer",fontSize:14,fontWeight:800}}>✅ 適用する</button><button onClick={onClose} style={{flex:1,background:"#d5edeb",color:"#3a8a87",border:"1px solid #90cbc8",borderRadius:8,padding:"11px 0",cursor:"pointer",fontSize:14}}>キャンセル</button></div>
      </div>
      {kp&&<NumericKeypad mode={kp.mode} value={kp.value} min={kp.min} max={kp.max} unit={kp.unit} anchorRect={kp.anchorRect} onConfirm={v=>{kp.onConfirm(v);setKp(null);}} onClose={()=>setKp(null)}/>}
    </div>
  );
}

function DownloadModal({ depts, staffList, allShifts, year, month, activeDeptId, allEvents, onClose }) {
  const [selectedDepts, setSelectedDepts] = useState([activeDeptId]);
  const noSelection = selectedDepts.length === 0;
  const fname = `シフト表_${year}年${month+1}月`;
  const toggleDept = (id) => setSelectedDepts(prev=>prev.includes(id)?prev.filter(x=>x!==id):[...prev,id]);
  const doDownload = (ext) => { if(noSelection)return; let content="",type=""; if(ext==="csv"){content=buildCSV(depts,staffList,allShifts,year,month,selectedDepts);type="text/csv;charset=utf-8";} if(ext==="html"){content=buildPrintHTML(depts,staffList,allShifts,year,month,selectedDepts,allEvents);type="text/html;charset=utf-8";} triggerDownload(content,`${fname}.${ext}`,type); };
  const doPrint = () => { if(noSelection)return; const html=buildPrintHTML(depts,staffList,allShifts,year,month,selectedDepts,allEvents); printWithIframe(html); onClose(); };
  return (
    <div style={{position:"fixed",inset:0,background:"#000000cc",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:"#f3fffe",border:"1px solid #90cbc8",borderRadius:14,padding:24,width:"100%",maxWidth:400,boxShadow:"0 30px 80px #000",maxHeight:"90vh",overflowY:"auto"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}><div><div style={{fontSize:15,fontWeight:900,color:"#1a3635"}}>📤 書き出し</div><div style={{fontSize:11,color:"#3a8a87",marginTop:2}}>{year}年{month+1}月</div></div><button onClick={onClose} style={{background:"none",border:"none",color:"#3a8a87",cursor:"pointer",fontSize:20}}>✕</button></div>
        <div style={{fontSize:11,color:"#3a8a87",fontWeight:700,marginBottom:7}}>対象部署</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:16}}>{depts.map(d=>{const sel=selectedDepts.includes(d.id);return<button key={d.id} onClick={()=>toggleDept(d.id)} style={{background:sel?"#8ecece":"transparent",color:sel?"#2BBFBA":"#2a5a57",border:`1px solid ${sel?"#2BBFBA":"#b8deda"}`,borderRadius:7,padding:"4px 10px",cursor:"pointer",fontSize:11,fontWeight:sel?700:400}}>{d.icon} {d.label}</button>;})}</div>
        {noSelection&&<div style={{fontSize:11,color:"#ef4444",marginBottom:10}}>⚠ 部署を1つ以上選択してください</div>}
        <button onClick={doPrint} disabled={noSelection} style={{width:"100%",background:noSelection?"#d5edec":"linear-gradient(135deg,#2BBFBA,#45B7D1)",border:"none",borderRadius:10,padding:"13px 16px",cursor:noSelection?"not-allowed":"pointer",display:"flex",alignItems:"center",gap:12,textAlign:"left",opacity:noSelection?0.4:1,marginBottom:8}}><span style={{fontSize:24}}>🖨️</span><div><div style={{fontSize:13,fontWeight:800,color:"#fff"}}>今すぐ印刷</div><div style={{fontSize:11,color:"#d5f5f5",marginTop:2}}>印刷ダイアログがすぐに開きます</div></div></button>
        <button onClick={()=>doDownload("csv")} disabled={noSelection} style={{width:"100%",background:noSelection?"#d5edec":"#e8f5ee",border:"1px solid #2d8a52",borderRadius:10,padding:"13px 16px",cursor:noSelection?"not-allowed":"pointer",display:"flex",alignItems:"center",gap:12,textAlign:"left",opacity:noSelection?0.4:1,marginBottom:8}}><span style={{fontSize:24}}>📊</span><div><div style={{fontSize:13,fontWeight:800,color:"#34d399"}}>CSV（Excel・スプレッドシート）</div><div style={{fontSize:11,color:"#3a8a87",marginTop:2}}>Excel・Googleスプレッドシートで開けます</div></div></button>
        <button onClick={()=>doDownload("html")} disabled={noSelection} style={{width:"100%",background:noSelection?"#d5edec":"#e8f8f7",border:"1px solid #8ecece",borderRadius:10,padding:"13px 16px",cursor:noSelection?"not-allowed":"pointer",display:"flex",alignItems:"center",gap:12,textAlign:"left",opacity:noSelection?0.4:1}}><span style={{fontSize:24}}>💾</span><div><div style={{fontSize:13,fontWeight:800,color:"#2BBFBA"}}>HTMLで保存（USB用）</div><div style={{fontSize:11,color:"#3a8a87",marginTop:2}}>他のPCやUSBで印刷する場合に使用</div></div></button>
      </div>
    </div>
  );
}

