                  reason             : `burnout高 夜勤${nc}回 — recovery優先`,
                  governanceImpact   : 'coverage gap risk — replacement planning needed',
                  protectedBypass    : false,
                  emergencyFlag      : false,
                  rollbackRecommended: false,
                  staffId            : e.s.id,
